/**
 * One row in the Git-tab Stashes view. `ref_name` is git's reflog selector
 * (`stash@{0}`); `sha` is the full commit SHA of the stash snapshot, so the
 * frontend opens the stash diff through the existing `commit_sha` path
 * (`git diff <sha>^..<sha>`, the range summarized below). `message` is the
 * stash description (git's reflog subject), `date` its ISO-8601 creation
 * time, and the `files_changed` / `additions` / `deletions` numstat matches
 * the diff a row expands to.
 */
export interface StashEntry {
  additions: number;
  date: string;
  deletions: number;
  files_changed: number;
  message: string;
  ref_name: string;
  sha: string;
}

/**
 * Stable selector for apply, pop, and drop. The backend must re-resolve
 * `ref_name` and reject the mutation if it no longer matches `expected_sha`.
 */
export interface StashMutationBody {
  expected_sha: string;
  feature_id: number;
  ref_name: string;
}

/**
 * Create a stash. A non-blank message is passed to Git; `None` or blank input
 * uses Git's default stash description. Untracked files are opt-in and ignored
 * files are never included.
 */
export interface StashPushBody {
  feature_id: number;
  include_untracked?: boolean;
  /** @nullable */
  message?: string | null;
}

export type SubagentRunStatus = (typeof SubagentRunStatus)[keyof typeof SubagentRunStatus];

export const SubagentRunStatus = {
  running: "running",
  completed: "completed",
  failed: "failed",
  stopped: "stopped",
} as const;

/**
 * One sub-agent as the desktop renders it: the transcript's sub-agent card
 * for its carrier. `action_count` is observed by Cadencr from the
 * sub-agent's transcript; every other field is a provider fact.
 */
export interface SubagentRun {
  /**
   * Tool calls Cadencr saw in the sub-agent's transcript.
   * @nullable
   */
  actionCount?: number | null;
  /** @nullable */
  agentName?: string | null;
  /** @nullable */
  agentType?: string | null;
  background: boolean;
  /** @nullable */
  childSessionId?: string | null;
  /** @nullable */
  description?: string | null;
  /** @nullable */
  durationMs?: number | null;
  /** @nullable */
  endedAt?: string | null;
  /** @nullable */
  model?: string | null;
  /** `model` is what the sub-agent ran on, not just what it was asked to use. */
  modelResolved: boolean;
  /**
   * Carrier of the sub-agent that launched this one, when nested.
   * @nullable
   */
  parentToolUseId?: string | null;
  /** @nullable */
  prompt?: string | null;
  /** @nullable */
  reasoningEffort?: string | null;
  /** @nullable */
  resultSummary?: string | null;
  sessionId: number;
  startedAt: string;
  status: SubagentRunStatus;
  /** @nullable */
  statusReason?: string | null;
  /**
   * Tool calls the provider reports the sub-agent made.
   * @nullable
   */
  toolUseCount?: number | null;
  /** The carrier tool_use id: joins the run to its transcript block. */
  toolUseId: string;
  /** @nullable */
  totalTokens?: number | null;
}

